var ResizeManager=Classy.newClass();ResizeManager.classFields({eventListeners:[],EVENTS:{RESIZE:"resize",REFRESH:"refresh"}});ResizeManager.classMethods({addEventListener:function(callback,context){ResizeManager.eventListeners.push({cb:callback,ctxt:context});},removeEventListener:function(callback,context){for(var i=0;i<ResizeManager.eventListeners.length;i++){if(ResizeManager.eventListeners[i].cb===callback&&ResizeManager.eventListeners[i].ctxt===context){ResizeManager.eventListeners.splice(i,1);return;}}},init:function(){$(window).resize(function(){ResizeManager._resize();});},refresh:function(){ResizeManager._updateSizes();ResizeManager._notifyEventListeners(ResizeManager.EVENTS.REFRESH,null);},_resize:function(){ResizeManager._updateSizes();ResizeManager._notifyEventListeners(ResizeManager.EVENTS.RESIZE,null);},_updateSizes:function(){$("#game").width($("#mainContent").width()+20);$("#game").height(Math.min($(window).height(),Math.floor(($("#game").width())*0.75)));$("#playerPanel").width($("#mainContent").width()+20);$("#playerPanel").height(Math.min(180,Math.floor(($("#playerPanel").width())*0.25)));$("#scrapyardSnippet .content").height($("#scrapyardSnippet .content").width()*0.185);},_notifyEventListeners:function(evt,data){for(var i=0;i<ResizeManager.eventListeners.length;i++){ResizeManager.eventListeners[i].cb(ResizeManager.eventListeners[i].ctxt,evt,data);}}});